import {useId,useLayoutEffect,useRef,useState} from 'react';
import './search.css';
export type FilterToken={id:string;label:string;expression:string};
export type SearchValue={tokens:FilterToken[];text:string};
export type Suggestion={id:string;label:string;token:FilterToken};
type Props={value:SearchValue;suggestions:Suggestion[];onChange:(value:SearchValue)=>void;onQuery:(text:string,editing:FilterToken|null)=>void;onSubmit:()=>void};
export function TokenSearch({value,suggestions,onChange,onQuery,onSubmit}:Props){
 const id=useId(),input=useRef<HTMLInputElement>(null),caret=useRef<number|null>(null);
 const [editing,setEditing]=useState<string|null>(null),[draft,setDraft]=useState(''),[active,setActive]=useState(-1),[expanded,setExpanded]=useState(false),[announcement,setAnnouncement]=useState('');
 const text=editing===null?value.text:draft;
 useLayoutEffect(()=>{if(caret.current!==null&&input.current){input.current.focus();input.current.setSelectionRange(caret.current,caret.current);caret.current=null}});
 function focusAt(n:number){caret.current=n}
 function edit(token:FilterToken){setEditing(token.id);setDraft(token.expression);onQuery(token.expression,token);setActive(-1);setExpanded(true);focusAt(token.expression.length);setAnnouncement('Editing filter '+token.label)}
 function remove(token:FilterToken){onChange({...value,tokens:value.tokens.filter(t=>t.id!==token.id)});if(editing===token.id)setEditing(null);focusAt(value.text.length);setAnnouncement('Removed filter '+token.label)}
 function choose(s:Suggestion){const tokens=editing===null?[...value.tokens,s.token]:value.tokens.map(t=>t.id===editing?{...s.token,id:t.id}:t);onChange({tokens,text:editing===null?'':value.text});setEditing(null);setExpanded(false);setActive(-1);focusAt(editing===null?0:value.text.length);setAnnouncement('Applied filter '+s.label)}
 return <form role="search" onSubmit={e=>{e.preventDefault();if(active>=0&&expanded&&suggestions[active])choose(suggestions[active]);else onSubmit()}}>
 <label htmlFor={id}>Search workspace</label><div className="token-search"><ol aria-label="Search filters">{value.tokens.map(t=><li key={t.id}><button type="button" aria-label={'Edit filter '+t.label} aria-pressed={editing===t.id} onClick={()=>edit(t)}>{t.label}</button><button type="button" aria-label={'Remove filter '+t.label} onClick={()=>remove(t)}>×</button></li>)}</ol>
 <input ref={input} id={id} type="search" role="combobox" aria-autocomplete="list" aria-expanded={expanded} aria-controls={id+'suggestions'} aria-activedescendant={expanded&&active>=0&&suggestions[active]?id+'option'+active:undefined} aria-describedby={id+'help'} value={text} onFocus={()=>setExpanded(true)} onChange={e=>{const next=e.target.value;if(editing===null)onChange({...value,text:next});else setDraft(next);onQuery(next,value.tokens.find(t=>t.id===editing)??null);setActive(-1);setExpanded(true)}} onKeyDown={e=>{if(e.nativeEvent.isComposing)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();setExpanded(true);setActive(n=>suggestions.length===0?-1:(n+(e.key==='ArrowDown'?1:-1)+suggestions.length)%suggestions.length)}else if(e.key==='Escape'){e.preventDefault();setEditing(null);setExpanded(false);setActive(-1);focusAt(value.text.length)}else if(e.key==='Backspace'&&text===''&&value.tokens.length&&editing===null){e.preventDefault();edit(value.tokens[value.tokens.length-1])}else if(e.key==='Tab'){setExpanded(false)}}}/>
 <button type="button" onClick={()=>{onChange({tokens:[],text:''});setEditing(null);setExpanded(false);focusAt(0);setAnnouncement('Search cleared')}}>Clear search</button><button type="submit">Search</button></div>
 <p id={id+'help'} className="search-help">Use arrow keys to choose a suggestion and Enter to apply. Edit filters with their buttons; Escape cancels editing.</p>
 <ul id={id+'suggestions'} role="listbox" aria-label="Search suggestions" hidden={!expanded}>{suggestions.map((s,i)=><li role="option" aria-selected={active===i} id={id+'option'+i} key={s.id} onPointerDown={e=>e.preventDefault()} onClick={()=>choose(s)}>{s.label}</li>)}</ul>
 <p role="status" className="sr-only">{announcement}</p></form>;
}
